def _choose_command(self, next_exec: int) -> Dict[str, Any]:
    px, py, bat = self.est.predict_at(next_exec - 1, self.cmds_by_tick)
    cur_c = self.nav.safe_cell_near(px, py)
    dt_home = self.nav.dt_to_base[cur_c]
    de_home = self.nav.de_to_base[cur_c]

    # Battery hysteresis protection: charge cleanly instead of oscillating
    if bat < 4.5:
        self.charging = True
    elif bat >= 14.0 or (next_exec + dt_home + 5.0 >= self.max_ticks):
        self.charging = False
    if self.charging and bat < 14.0 and (next_exec + dt_home + 6.0 < self.max_ticks):
        return {"action": "wait"}
    if bat < 3.0:
        return {"action": "wait"}
